}

int main(int argc, char **argv)
{
    if (argc < 2) {
        return usage(argv[0]);
    }
    if (strcmp(argv[1], "index") == 0) {
        const char *out = NULL;
        if (argc >= 4 && strcmp(argv[2], "--linked") == 0) {
            for (int i = 4; i < argc; i++) {
                if (strcmp(argv[i], "-o") == 0 && i + 1 < argc) {
                    out = argv[i + 1];
