            int rc = sf_index_objects(objs, obj_count, out);
            free(objs);
            return rc == 0 ? 0 : 1;
        }
        return usage(argv[0]);
    }
    if (strcmp(argv[1], "check") == 0 && argc == 4) {
        return sf_check(argv[2], argv[3]);
